:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --ink: #14140f;
  --ink-2: #3b3b34;
  --muted: #6b6b62;
  --line: #e6e4dc;
  --accent: #2a4a3a;
  --accent-2: #c46a3a;
  --sale: #b8412c;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(20,20,15,.06);
  --shadow: 0 8px 30px rgba(20,20,15,.08);
  --container: 1240px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-display: 'Fraunces', Georgia, 'Times New Roman', serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #15140f;
    --surface: #1d1c17;
    --ink: #f4f2ea;
    --ink-2: #d8d5cb;
    --muted: #a09d92;
    --line: #2c2a23;
    --accent: #8fb39d;
    --accent-2: #e09064;
  }
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }
}

body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }

h1, h2, h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: -0.01em;
  margin: 0;
  color: var(--ink);
}
h1 { font-size: clamp(2.4rem, 5vw + 1rem, 4.4rem); line-height: 1.05; letter-spacing: -0.025em; }
h2 { font-size: clamp(1.6rem, 2vw + 1rem, 2.4rem); line-height: 1.15; }
h3 { font-size: 1.15rem; line-height: 1.3; }

p { margin: 0; color: var(--ink-2); }

/* Focus */
:focus { outline: none; }
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  top: -100px; left: 1rem;
  background: var(--ink);
  color: var(--bg);
  padding: .75rem 1rem;
  border-radius: var(--radius-sm);
  z-index: 100;
  font-weight: 600;
}
.skip-link:focus { top: 1rem; }

.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* ---------- Header ---------- */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250,250,247,.85);
  backdrop-filter: saturate(180%) blur(12px);
  -webkit-backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--line);
}
@media (prefers-color-scheme: dark) {
  .site-header { background: rgba(21,20,15,.85); }
}

.header-inner {
  display: flex; align-items: center; gap: 1.5rem;
  min-height: 72px;
}

.brand {
  display: inline-flex; align-items: center; gap: .5rem;
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.brand:hover { text-decoration: none; }
.brand-mark { font-size: 1.4em; color: var(--accent); line-height: 1; }
.brand-name { text-transform: lowercase; }

.primary-nav { flex: 1; }
.primary-nav ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 1.75rem;
  justify-content: center;
}
.primary-nav a {
  font-size: .94rem;
  font-weight: 500;
  color: var(--ink-2);
  padding: .5rem 0;
  position: relative;
}
.primary-nav a:hover { color: var(--ink); text-decoration: none; }
.primary-nav a::after {
  content: '';
  position: absolute; left: 0; right: 0; bottom: 0;
  height: 2px; background: var(--ink);
  transform: scaleX(0); transform-origin: left;
  transition: transform .2s ease;
}
.primary-nav a:hover::after { transform: scaleX(1); }

.header-actions { display: flex; gap: .25rem; align-items: center; }

.icon-btn {
  background: transparent;
  border: 0;
  width: 44px; height: 44px;
  border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ink);
  cursor: pointer;
  position: relative;
  transition: background .15s ease;
}
.icon-btn:hover { background: var(--line); }

.cart-count {
  position: absolute;
  top: 6px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  background: var(--accent-2);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  display: inline-flex; align-items: center; justify-content: center;
  line-height: 1;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: .5rem;
  padding: .85rem 1.4rem;
  border-radius: 999px;
  font-weight: 600;
  font-size: .95rem;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: transform .15s ease, background .15s ease, color .15s ease, border-color .15s ease;
  text-decoration: none;
  white-space: nowrap;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn-sm { padding: .6rem 1.05rem; font-size: .88rem; }

.btn-primary {
  background: var(--ink);
  color: var(--bg);
  border-color: var(--ink);
}
.btn-primary:hover { background: var(--accent); border-color: var(--accent); }

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-ghost:hover { background: var(--ink); color: var(--bg); }

/* ---------- Eyebrows / shared ---------- */
.eyebrow {
  font-family: var(--font-sans);
  font-size: .78rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent-2);
  margin: 0 0 .5rem;
}
.eyebrow-light { color: rgba(255,255,255,.85); }

.section-title { margin-top: .25rem; }

.section-header {
  display: flex; align-items: end; justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.link-arrow {
  font-weight: 600;
  font-size: .95rem;
  color: var(--ink);
  border-bottom: 1.5px solid var(--ink);
  padding-bottom: 2px;
}
.link-arrow:hover { text-decoration: none; color: var(--accent); border-color: var(--accent); }

/* ---------- Hero ---------- */
.hero { padding: clamp(2.5rem, 6vw, 5rem) 0 clamp(3rem, 7vw, 6rem); }

.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}

.hero-copy { max-width: 560px; }
.hero-copy h1 { margin-top: .5rem; }
.lede {
  font-size: 1.15rem;
  color: var(--ink-2);
  margin: 1.25rem 0 2rem;
  max-width: 48ch;
}

.hero-cta { display: flex; gap: .75rem; flex-wrap: wrap; }

.hero-meta {
  list-style: none; padding: 0; margin: 2.5rem 0 0;
  display: flex; gap: 1.75rem; flex-wrap: wrap;
  font-size: .88rem; color: var(--muted);
}
.hero-meta li { display: flex; align-items: center; gap: .5rem; }
.hero-meta li::before {
  content: '';
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--accent);
  display: inline-block;
}

.hero-visual {
  position: relative;
  aspect-ratio: 5 / 6;
  min-height: 380px;
}
.hero-card {
  position: absolute;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.hero-card-1 {
  inset: 0 30% 25% 0;
  background:
    radial-gradient(circle at 30% 30%, #d4c4a8 0%, #b89968 60%, #8d7142 100%);
}
.hero-card-2 {
  top: 18%; right: 0; bottom: 8%; left: 38%;
  background:
    linear-gradient(135deg, #2a4a3a 0%, #4a7a5e 100%);
}
.hero-card-3 {
  bottom: 0; left: 12%; right: 35%; top: 60%;
  background:
    linear-gradient(135deg, #e8ddc8 0%, #c9b896 100%);
}
.hero-card::after {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(circle at 70% 20%, rgba(255,255,255,.3), transparent 60%);
  pointer-events: none;
}
.hero-badge {
  position: absolute;
  top: -8px; right: -8px;
  width: 64px; height: 64px;
  background: var(--accent-2);
  color: #fff;
  border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 600;
  box-shadow: var(--shadow);
  z-index: 2;
}

/* ---------- Categories ---------- */
.categories { padding: 2.5rem 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.categories .section-title { font-size: 1.15rem; font-family: var(--font-sans); font-weight: 600; margin-bottom: 1.5rem; letter-spacing: 0; }

.category-list {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}
.category-list a {
  display: flex; flex-direction: column; align-items: center; gap: .75rem;
  padding: .75rem;
  border-radius: var(--radius-sm);
  font-size: .92rem;
  font-weight: 500;
  color: var(--ink);
  transition: background .15s ease;
}
.category-list a:hover { background: var(--surface); text-decoration: none; }
.category-thumb {
  width: 72px; height: 72px;
  border-radius: 50%;
  background: var(--line);
}
.cat-1 { background: linear-gradient(135deg,#e8ddc8,#b89968); }
.cat-2 { background: linear-gradient(135deg,#d4d4cc,#8a8a7e); }
.cat-3 { background: linear-gradient(135deg,#cfdde0,#7d9aa1); }
.cat-4 { background: linear-gradient(135deg,#e3c9bd,#a86a55); }
.cat-5 { background: linear-gradient(135deg,#c9d9c0,#5e7a52); }
.cat-6 { background: linear-gradient(135deg,#e8d4dc,#a16881); }

/* ---------- Products ---------- */
.featured { padding: clamp(3rem, 6vw, 5rem) 0; }

.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.75rem 1.25rem;
}

.product {
  display: flex; flex-direction: column; gap: .75rem;
  position: relative;
}

.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
}
.product-media .swatch {
  position: absolute; inset: 0;
}
.product-media::after {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.35), transparent 55%);
  pointer-events: none;
}

.tag {
  position: absolute; top: .8rem; left: .8rem;
  background: var(--bg);
  color: var(--ink);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: .35rem .6rem;
  border-radius: 999px;
  z-index: 2;
}
.tag-sale { background: var(--sale); color: #fff; }
.tag-new { background: var(--ink); color: var(--bg); }

.add-btn {
  position: absolute; right: .75rem; bottom: .75rem;
  width: 40px; height: 40px;
  border-radius: 50%;
  border: 0;
  background: var(--bg);
  color: var(--ink);
  cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-sm);
  opacity: 0;
  transform: translateY(6px);
  transition: opacity .2s ease, transform .2s ease, background .15s ease;
  z-index: 2;
}
.add-btn:hover { background: var(--ink); color: var(--bg); }
.product:hover .add-btn,
.product:focus-within .add-btn { opacity: 1; transform: translateY(0); }
.add-btn:focus-visible { opacity: 1; transform: translateY(0); }

.product-info {
  display: flex; align-items: baseline; justify-content: space-between;
  gap: 1rem;
}
.product-info h3 {
  font-family: var(--font-sans);
  font-size: .98rem;
  font-weight: 500;
  color: var(--ink);
}
.product-info h3 a { color: inherit; }
.product-info h3 a::after {
  content: '';
  position: absolute; inset: 0;
}
.product-meta { font-size: .82rem; color: var(--muted); margin-top: .15rem; }
.product-price {
  font-size: .98rem;
  font-weight: 600;
  color: var(--ink);
  white-space: nowrap;
}
.product-price s { color: var(--muted); font-weight: 400; margin-left: .35rem; font-size: .85rem; }

/* ---------- Deals ---------- */
.deals {
  padding: clamp(3rem, 6vw, 5rem) 0;
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.deals-timer {
  font-size: .92rem;
  color: var(--muted);
}
.deals-timer time {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  color: var(--ink);
  background: var(--bg);
  padding: .35rem .6rem;
  border-radius: var(--radius-sm);
  margin-left: .35rem;
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: 1fr 1fr;
  gap: 1.25rem;
}

.deal {
  background: var(--bg);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  transition: transform .2s ease, box-shadow .2s ease;
}
.deal:hover { transform: translateY(-2px); box-shadow: var(--shadow); }

.deal-large {
  grid-column: 1 / 2;
  grid-row: 1 / span 2;
  background: linear-gradient(160deg, #2a4a3a 0%, #1a3528 100%);
  color: #fff;
  border-color: transparent;
}
.deal-large h3,
.deal-large p { color: rgba(255,255,255,.92); }
.deal-large h3 {
  font-family: var(--font-display);
  font-size: 2rem;
  margin: .25rem 0 .5rem;
  color: #fff;
}
.deal-large .deal-body { padding: 2rem; gap: 1rem; }

.deal-art {
  aspect-ratio: 16 / 10;
  background: var(--line);
}
.deal-large .deal-art { aspect-ratio: 4 / 3; }

.deal-art-1 {
  background:
    radial-gradient(circle at 60% 40%, #d8c8a8 0%, #b09368 50%, transparent 75%),
    linear-gradient(135deg, #3a5a48, #1a3528);
}
.deal-art-2 {
  background:
    radial-gradient(circle at 30% 50%, #e8d4c0 0%, #c4956d 60%, #8a5e3a 100%);
}
.deal-art-3 {
  background:
    linear-gradient(135deg, #d4c0a8 0%, #a88864 100%);
}

.deal-body {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  flex: 1;
  align-items: flex-start;
}
.deal-body h3 {
  font-family: var(--font-sans);
  font-size: 1.1rem;
  font-weight: 600;
}

.deal-price {
  display: flex; align-items: baseline; gap: .5rem;
  margin: .25rem 0 .5rem;
}
.price-now { font-size: 1.25rem; font-weight: 700; color: inherit; }
.price-was { color: var(--muted); font-size: .9rem; }
.deal-large .price-was { color: rgba(255,255,255,.65); }
.price-tag {
  background: var(--sale);
  color: #fff;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .05em;
  padding: .2rem .5rem;
  border-radius: 999px;
}

/* ---------- Editorial ---------- */
.editorial { padding: clamp(3rem, 6vw, 5rem) 0; }

.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.5rem;
}

.story {
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line);
  transition: transform .2s ease, box-shadow .2s ease;
}
.story:hover { transform: translateY(-2px); box-shadow: var(--shadow); }

.story-link {
  display: block;
  height: 100%;
  color: inherit;
}
.story-link:hover { text-decoration: none; }
.story-link h3 { transition: color .15s ease; }
.story-link:hover h3 { color: var(--accent); }

.story-feature {
  grid-column: 1 / 2;
  grid-row: 1 / span 2;
}
.story-feature .story-art { aspect-ratio: 4 / 5; }
.story-feature h3 { font-size: 1.6rem; }

.story-art {
  aspect-ratio: 16 / 10;
  background: var(--line);
}
.story-art-1 {
  background:
    radial-gradient(circle at 30% 40%, #ede4d2 0%, #c9b896 60%, #8a7152 100%);
}
.story-art-2 {
  background: linear-gradient(160deg, #d4dbd0, #6e8a72);
}
.story-art-3 {
  background: linear-gradient(160deg, #e0d0c0, #a87856);
}
.story-art-4 {
  background: linear-gradient(160deg, #d8d2c4, #8a7a64);
}

.story-body {
  padding: 1.5rem;
  display: flex; flex-direction: column; gap: .5rem;
}
.story-body h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  line-height: 1.25;
}
.byline {
  font-size: .82rem;
  color: var(--muted);
  margin-top: .5rem;
}

/* ---------- Newsletter ---------- */
.newsletter {
  padding: clamp(3rem, 6vw, 5rem) 0;
  background: var(--ink);
  color: var(--bg);
}
.newsletter h2 { color: var(--bg); }
.newsletter p { color: rgba(255,255,255,.75); margin-top: .5rem; max-width: 44ch; }

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}

.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: .5rem;
  position: relative;
}
.news-form input {
  font: inherit;
  padding: .95rem 1.2rem;
  border-radius: 999px;
  border: 1.5px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.05);
  color: var(--bg);
  font-size: 1rem;
}
.news-form input::placeholder { color: rgba(255,255,255,.5); }
.news-form input:focus-visible {
  outline: 2px solid var(--accent-2);
  outline-offset: 2px;
  border-color: var(--accent-2);
}
.news-form .btn-primary {
  background: var(--bg);
  color: var(--ink);
  border-color: var(--bg);
}
.news-form .btn-primary:hover { background: var(--accent-2); border-color: var(--accent-2); color: #fff; }

.news-status {
  grid-column: 1 / -1;
  font-size: .88rem;
  color: rgba(255,255,255,.85);
  min-height: 1.2em;
  margin: 0;
  padding: 0 .5rem;
}
.news-status.error { color: #ffb4a3; }

/* ---------- Footer ---------- */
.site-footer {
  background: var(--bg);
  border-top: 1px solid var(--line);
  padding: 3rem 0 1.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid var(--line);
}

.footer-brand {
  display: flex; flex-direction: column; gap: .25rem;
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 600;
  color: var(--ink);
}
.footer-brand p { font-family: var(--font-sans); font-size: .9rem; font-weight: 400; color: var(--muted); margin-top: .5rem; }
.footer-brand .brand-mark { color: var(--accent); display: inline-block; margin-right: .25rem; }

.footer-heading {
  font-family: var(--font-sans);
  font-size: .82rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--ink);
  margin: 0 0 1rem;
}

.site-footer ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-direction: column; gap: .65rem;
}
.site-footer a {
  color: var(--ink-2);
  font-size: .92rem;
}
.site-footer a:hover { color: var(--ink); }

.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 1.5rem;
  font-size: .85rem;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-legal {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 1.5rem;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: var(--bg);
  padding: .85rem 1.4rem;
  border-radius: 999px;
  box-shadow: var(--shadow);
  font-size: .92rem;
  font-weight: 500;
  z-index: 200;
  opacity: 0;
  transition: opacity .25s ease, transform .25s ease;
  pointer-events: none;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ---------- Forced colors ---------- */
@media (forced-colors: active) {
  .btn,
  .icon-btn,
  .product-media,
  .deal,
  .story,
  .hero-card,
  .category-thumb {
    border: 1px solid CanvasText;
  }
  .btn-primary { background: ButtonText; color: ButtonFace; }
}

/* ---------- Responsive ---------- */
@media (max-width: 1000px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-visual { max-width: 520px; margin-inline: auto; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .category-list { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .deal-large { grid-column: 1 / -1; grid-row: auto; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-feature { grid-column: 1 / -1; grid-row: auto; }
  .story-feature .story-art { aspect-ratio: 16 / 9; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-inner { grid-template-columns: 1fr; }
}

@media (max-width: 680px) {
  .header-inner { gap: .5rem; min-height: 64px; }
  .primary-nav { display: none; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 1.5rem 1rem; }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .category-list { grid-template-columns: repeat(3, 1fr); gap: .5rem; }
  .category-thumb { width: 60px; height: 60px; }
  .hero-meta { gap: 1rem; }
  .footer-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .news-form { grid-template-columns: 1fr; }
  .news-form .btn-primary { width: 100%; }
}

