+    name: 'Maru Wood Tray',
+    meta: 'White oak · Round',
+    price: 76,
+    was: null,
+    tag: null,
+    swatch: 'linear-gradient(135deg, #e8d4b8 0%, #a07a4a 100%)'
+  },
+  {
+    id: 'p8',
+    name: 'Kiln Espresso Cups',
+    meta: 'Set of 4',
+    price: 52,
+    was: 68,
+    tag: 'sale',
+    swatch: 'radial-gradient(circle at 35% 30%, #e8d4dc 0%, #a16881 100%)'
+  }
+];
+
+function money(n) {
+  return '$' + n.toFixed(0);
+}
+
+function renderProducts() {
+  const grid = document.getElementById('product-grid');
+  if (!grid) return;
+
+  grid.innerHTML = products.map(p => {
+    const tagHtml = p.tag === 'sale'
+      ? '<span class="tag tag-sale">Sale</span>'
+      : p.tag === 'new'
+        ? '<span class="tag tag-new">New</span>'
+        : '';
+    const priceHtml = p.was
+      ? `${money(p.price)} <s>${money(p.was)}</s>`
+      : money(p.price);
+    const ariaPrice = p.was
+      ? `On sale for ${money(p.price)}, was ${money(p.was)}`
+      : `Price ${money(p.price)}`;
+
+    return `
+      <li class="product">
+        <div class="product-media">
+          <span class="swatch" style="background: ${p.swatch};" aria-hidden="true"></span>
+          ${tagHtml}
+          <button type="button" class="add-btn" data-id="${p.id}" aria-label="Add ${p.name} to cart">
+            <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14M5 12h14"/></svg>
+          </button>
+        </div>
+        <div class="product-info">
+          <div>
+            <h3><a href="#">${p.name}</a></h3>
+            <p class="product-meta">${p.meta}</p>
+          </div>
+          <p class="product-price" aria-label="${ariaPrice}">${priceHtml}</p>
+        </div>
+      </li>
+    `;
+  }).join('');
+}
+
+// Cart
+let cartCount = 2;
+function updateCart(delta) {
+  cartCount += delta;
+  const el = document.getElementById('cart-count');
+  const btn = document.getElementById('cart-btn');
+  if (el) el.textContent = cartCount;
+  if (btn) btn.setAttribute('aria-label', `Cart, ${cartCount} item${cartCount === 1 ? '' : 's'}`);
+}
+
+// Toast
+let toastTimer;
+function showToast(message) {
+  const toast = document.getElementById('toast');
+  if (!toast) return;
+  toast.textContent = message;
+  toast.hidden = false;
+  // force reflow so the transition runs
+  void toast.offsetWidth;
+  toast.classList.add('show');
+  clearTimeout(toastTimer);
+  toastTimer = setTimeout(() => {
+    toast.classList.remove('show');
+    setTimeout(() => { toast.hidden = true; }, 300);
+  }, 2200);
+}
+
+// Wire add-to-cart (event delegation)
+function wireProductActions() {
+  const grid = document.getElementById('product-grid');
+  if (!grid) return;
+  grid.addEventListener('click', (e) => {
+    const btn = e.target.closest('.add-btn');
+    if (!btn) return;
+    e.preventDefault();
+    const id = btn.dataset.id;
+    const product = products.find(p => p.id === id);
+    updateCart(1);
+    showToast(`Added “${product ? product.name : 'item'}” to cart`);
+  });
+}
+
+// Deals countdown — counts down to next Sunday midnight
+function startCountdown() {
+  const el = document.getElementById('countdown');
+  if (!el) return;
+
+  function nextSunday() {
+    const now = new Date();
+    const d = new Date(now);
+    const days = (7 - now.getDay()) % 7 || 7;
+    d.setDate(now.getDate() + days);
+    d.setHours(0, 0, 0, 0);
+    return d;
+  }
+
+  const target = nextSunday();
+
+  function tick() {
+    const now = new Date();
+    let diff = Math.max(0, target - now);
+    const days = Math.floor(diff / 86400000); diff -= days * 86400000;
+    const hours = Math.floor(diff / 3600000); diff -= hours * 3600000;
+    const mins = Math.floor(diff / 60000); diff -= mins * 60000;
+    const secs = Math.floor(diff / 1000);
+    const pad = (n) => String(n).padStart(2, '0');
+    el.textContent = `${days}d ${pad(hours)}:${pad(mins)}:${pad(secs)}`;
+  }
+
+  tick();
+  setInterval(tick, 1000);
+}
+
+// Newsletter
+function wireNewsletter() {
+  const form = document.getElementById('news-form');
+  if (!form) return;
+  const input = document.getElementById('news-email');
+  const status = document.getElementById('news-status');
+
+  form.addEventListener('submit', (e) => {
+    e.preventDefault();
+    const value = input.value.trim();
+    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
+    status.classList.remove('error');
+    if (!valid) {
+      status.classList.add('error');
+      status.textContent = 'Please enter a valid email address.';
+      input.setAttribute('aria-invalid', 'true');
+      input.focus();
+      return;
+    }
+    input.removeAttribute('aria-invalid');
+    status.textContent = `Thanks — we'll send notes to ${value}.`;
+    input.value = '';
+  });
+
+  input.addEventListener('input', () => {
+    if (input.getAttribute('aria-invalid') === 'true') {
+      input.removeAttribute('aria-invalid');
+      status.classList.remove('error');
+      status.textContent = '';
+    }
+  });
+}
+
+// Init
+document.addEventListener('DOMContentLoaded', () => {
+  renderProducts();
+  wireProductActions();
+  startCountdown();
+  wireNewsletter();
+});
+
')

