.cat-5 { background: linear-gradient(135deg,#c9d9c0,#5e7a52); }
.cat-6 { background: linear-gradient(135deg,#e8d4dc,#a16881); }

/* ---------- Products ---------- */
.featured { padding: clamp(3rem, 6vw, 5rem) 0; }

.product-grid {
