.product-price s { color: var(--muted); font-weight: 400; margin-left: .35rem; font-size: .85rem; }

/* ---------- Deals ---------- */
.deals {
  padding: clamp(3rem, 6vw, 5rem) 0;
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

