.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}

.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: .5rem;
  position: relative;
}
.news-form input {
  font: inherit;
  padding: .95rem 1.2rem;
  border-radius: 999px;
  border: 1.5px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.05);
